WITH metrics AS (SELECT *, ROUND(amount / SUM(amount) OVER (PARTITION BY channel), 4) AS amount_share, SUM(discount) OVER (PARTITION BY customer_id) AS customer_id_sum_discount, ROW_NUMBER() OVER (PARTITION BY customer_id, channel ORDER BY discount DESC, id) AS row_seq, CUME_DIST() OVER (PARTITION BY channel ORDER BY shipping_fee DESC) AS shipping_fee_cume_dist FROM orders) SELECT s.id, s.customer_id, s.store_id, s.status, s.shipping_fee, s.customer_id_sum_discount, s.row_seq, s.shipping_fee_cume_dist, (SELECT AVG(x.shipping_fee) FROM orders x WHERE x.store_id = s.store_id) AS avg_order_shipping_fee FROM metrics s ORDER BY store_id DESC
